// Mihomo / Clash.Meta self-built subscription override script.
//
// Works with both inline `proxies` subscriptions and provider-based
// subscriptions generated by the Worker/subconverter chain.

const SELF_NODE_NAMES = ["阿里云中转"];
const WORKER_SOURCE_PATH_KEYWORDS = ["/__node_source/"];

function main(config) {
  const nextConfig = config || {};
  if (!shouldApplyToSelfBuilt(nextConfig)) {
    return nextConfig;
  }

  nextConfig.profile = {
    "store-selected": true,
    "store-fake-ip": false,
  };

  nextConfig["geox-url"] = {
    geoip: "https://github.com/MetaCubeX/meta-rules-dat/releases/download/latest/geoip.dat",
    geosite: "https://github.com/MetaCubeX/meta-rules-dat/releases/download/latest/geosite.dat",
    mmdb: "https://github.com/MetaCubeX/meta-rules-dat/releases/download/latest/country.mmdb",
    asn: "https://github.com/MetaCubeX/meta-rules-dat/releases/download/latest/GeoLite2-ASN.mmdb",
  };

  nextConfig.hosts = {
    "doh.pub": ["1.12.12.21", "1.12.12.12"],
    "dns.google": ["8.8.8.8", "8.8.4.4"],
    "dns.alidns.com": ["223.5.5.5", "223.6.6.6"],
    "cloudflare-dns.com": ["1.1.1.1", "1.0.0.1"],
  };

  nextConfig.sniffer = {
    enable: true,
    "parse-pure-ip": true,
    sniff: {
      HTTP: { ports: [80, "8080-8880"], "override-destination": true },
      QUIC: { ports: [443, 8443] },
      TLS: { ports: [443, 8443] },
    },
  };

  nextConfig.dns = nextConfig.dns || {};
  const defaultDnsConfig = {
    enable: true,
    listen: "0.0.0.0:5053",
    ipv6: false,
    "filter-aaaa": true,
    "use-system-hosts": false,
    "enhanced-mode": "fake-ip",
    "fake-ip-range": "198.18.0.1/16",
    "fake-ip-filter-mode": "blacklist",
    "respect-rules": true,
    "fake-ip-filter": [
      "+.lan", "+.local", "+.msftconnecttest.com", "+.msftncsi.com",
      "localhost.ptlogin2.qq.com", "time.*.com", "stun.*.*",
      "+.srv.nintendo.net", "+.stun.playstation.net", "+.xboxlive.com",
    ],
    "default-nameserver": ["223.5.5.5", "119.29.29.29"],
    nameserver: [
      "https://doh.pub/dns-query",
      "https://dns.alidns.com/dns-query",
    ],
    fallback: [
      "https://1.1.1.1/dns-query",
      "https://8.8.8.8/dns-query",
      "https://dns.google/dns-query",
    ],
    "fallback-filter": {
      geoip: true,
      "geoip-code": "CN",
      geosite: ["gfw"],
      ipcidr: ["240.0.0.0/4"],
    },
    "direct-nameserver": ["https://doh.pub/dns-query", "https://dns.alidns.com/dns-query"],
    "direct-nameserver-follow-policy": false,
  };

  nextConfig.dns = { ...defaultDnsConfig, ...nextConfig.dns };
  return nextConfig;
}

function shouldApplyToSelfBuilt(config) {
  const proxies = Array.isArray(config.proxies) ? config.proxies : [];
  if (proxies.length > 0) {
    const names = proxies.map(proxy => normalizeName(proxy && proxy.name)).filter(Boolean);
    if (SELF_NODE_NAMES.some(name => names.some(proxyName => proxyName === normalizeName(name) || proxyName.includes(normalizeName(name))))) {
      return true;
    }
  }

  const providers = config["proxy-providers"];
  if (!providers || typeof providers !== "object") {
    return false;
  }

  return Object.values(providers).some(provider => isWorkerNodeSourceProvider(provider));
}

function isWorkerNodeSourceProvider(provider) {
  const url = String(provider && provider.url ? provider.url : "").trim();
  if (!url) {
    return false;
  }

  return WORKER_SOURCE_PATH_KEYWORDS.some(keyword => url.includes(keyword));
}

function normalizeName(value) {
  return typeof value === "string" ? value.trim().toLowerCase() : "";
}
